// NewConfirmIntentPayload builds a surla service confirm_intent endpoint
// payload.
func NewConfirmIntentPayload(body *ConfirmIntentRequestBody) *surla.ConfirmIntentPayload {
	v := &surla.ConfirmIntentPayload{
		ChangeID:        *body.ChangeID,
		RequestRevision: *body.RequestRevision,
	}
	v.Answers = make(map[string]string, len(body.Answers))
	for key, val := range body.Answers {
		tk := key
		tv := val
		v.Answers[tk] = tv
	}
	v.Examples = make([]*surla.ExampleItem, len(body.Examples))
	for i, val := range body.Examples {
		if val == nil {
			v.Examples[i] = nil
			continue
		}
		v.Examples[i] = unmarshalExampleItemRequestBodyToSurlaExampleItem(val)
	}

	return v
}

